create extension if not exists pgcrypto;
create table if not exists users(id uuid primary key default gen_random_uuid(),name text not null,email text unique not null,password_hash text not null,role text not null default 'customer' check(role in('customer','admin')),created_at timestamptz default now());
create table if not exists categories(id uuid primary key default gen_random_uuid(),name text unique not null);
create table if not exists products(id uuid primary key default gen_random_uuid(),name text not null,description text not null,price numeric(12,2) not null check(price>=0),stock integer not null default 0 check(stock>=0),category_id uuid references categories(id),image_url text,active boolean not null default true,created_at timestamptz default now());
create table if not exists cart_items(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete cascade,product_id uuid references products(id),quantity integer not null check(quantity>0),unique(user_id,product_id));
create table if not exists coupons(id uuid primary key default gen_random_uuid(),code text unique not null,type text check(type in('percentage','fixed')),value numeric(12,2) not null,min_spend numeric(12,2) default 0,expires_at timestamptz not null,usage_limit integer,per_customer_limit integer,used_count integer default 0,active boolean default true);
create table if not exists orders(id uuid primary key default gen_random_uuid(),user_id uuid references users(id),status text not null default 'pending_payment',subtotal numeric(12,2) not null,discount numeric(12,2) not null default 0,total numeric(12,2) not null,shipping_address text not null,idempotency_key text not null, gateway_checkout_id text unique,paid_at timestamptz,created_at timestamptz default now(),unique(user_id,idempotency_key));
create table if not exists order_items(id uuid primary key default gen_random_uuid(),order_id uuid references orders(id) on delete cascade,product_id uuid references products(id),name text not null,unit_price numeric(12,2) not null,quantity integer not null,line_total numeric(12,2) not null);
create table if not exists payments(id uuid primary key default gen_random_uuid(),order_id uuid unique references orders(id),status text not null, gateway_checkout_id text unique, gateway_payment_id text,amount numeric(12,2) not null,currency text not null default 'PHP',raw_payload jsonb,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists payment_events(id uuid primary key default gen_random_uuid(),event_id text unique not null,payload jsonb not null,received_at timestamptz default now());
create table if not exists coupon_uses(id uuid primary key default gen_random_uuid(),coupon_id uuid references coupons(id),user_id uuid references users(id),order_id uuid unique references orders(id),created_at timestamptz default now());
create table if not exists order_status_history(id uuid primary key default gen_random_uuid(),order_id uuid references orders(id) on delete cascade,status text not null,actor_id uuid references users(id),created_at timestamptz default now());
create index if not exists products_category_idx on products(category_id);create index if not exists orders_user_idx on orders(user_id);create index if not exists orders_status_idx on orders(status);
